-- Website contact, hall-booking and reservation requests, plus email bookkeeping
-- for catering_inquiries.
--
-- Until 2026-11-05 these three forms went only to formsubmit.co, which emailed
-- support@. When formsubmit.co went down (Cloudflare 522, 2026-11-05) every
-- message was lost and the guest saw an error page. Now each form is recorded
-- here first by the submit-website-form Edge Function, which then emails info@
-- itself through Resend (catering: create-catering-lead does the same for
-- catering_inquiries).
--
-- submission_id is generated by the browser, once per filled-in form, and sent on
-- every retry: the UNIQUE constraint makes a retry or double click a no-op.
--
-- notified_at / notify_error: when the team email went out, or why it did not
-- (rate_limited, resend_<status>, no_api_key). A retry of a submission whose email
-- failed tries the email again.
--
-- ip_hash: HMAC of the client IP, only to rate-limit abuse of the email sending;
-- the IP itself is never stored.
--
-- Only the Edge Functions (service role) read or write these tables.

CREATE TABLE public.website_messages (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  created_at      timestamptz NOT NULL DEFAULT now(),
  submission_id   uuid NOT NULL CONSTRAINT website_messages_submission_id_key UNIQUE,
  kind            text NOT NULL CHECK (kind IN ('contact','hall','reservation')),
  form_page       text,
  name            text NOT NULL,
  phone           text,
  email           text,
  -- Kind-specific answers (event date, guests, party size, time...), as entered.
  fields          jsonb NOT NULL DEFAULT '{}'::jsonb,
  message         text,
  attribution     jsonb,
  request_context jsonb,
  ip_hash         text,
  status          text NOT NULL DEFAULT 'new' CHECK (status IN ('new','handled','spam')),
  notified_at     timestamptz,
  notify_error    text
);

CREATE INDEX website_messages_created_idx ON public.website_messages (created_at DESC);
CREATE INDEX website_messages_ip_idx ON public.website_messages (ip_hash, created_at DESC);

ALTER TABLE public.website_messages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.website_messages FROM anon, authenticated;

ALTER TABLE public.catering_inquiries
  ADD COLUMN ip_hash      text,
  ADD COLUMN notified_at  timestamptz,
  ADD COLUMN notify_error text;

CREATE INDEX catering_inquiries_ip_idx ON public.catering_inquiries (ip_hash, created_at DESC);
